package com.northstarbank.console.integration;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.*;
@Component public class TierClient{
 private final RestClient entitlements,core;private final String secret;
 public TierClient(RestClient.Builder b,@Value("${app.entitlements-url}")String e,@Value("${app.core-url}")String c,@Value("${app.internal-secret}")String s){entitlements=b.baseUrl(e).build();core=b.baseUrl(c).build();secret=s;}
 public Login login(String email,String password){return entitlements.post().uri("/internal/login").header("X-Internal-Client",secret).body(Map.of("email",email,"password",password)).retrieve().body(Login.class);}
 public Decision decide(String token,String action,String branch,boolean vulnerable,String requester){Map<String,Object> body=new HashMap<>();body.put("action",action);body.put("vulnerable",vulnerable);if(branch!=null)body.put("branch",branch);if(requester!=null)body.put("requester",requester);return entitlements.post().uri("/internal/decide").header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).body(body).retrieve().body(Decision.class);}
 public List<Customer> search(String token,String q){Customer[] x=core.get().uri(u->u.path("/core/customers/search").queryParam("q",q).build()).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().body(Customer[].class);return x==null?List.of():List.of(x);}
 public Customer360 customer(String token,String id){return core.get().uri("/core/customers/{id}",id).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().body(Customer360.class);}
 public Customer updateContact(String token,String id,String phone,String email){return core.patch().uri("/core/customers/{id}/contact",id).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).body(Map.of("phone",phone,"email",email)).retrieve().body(Customer.class);}
 public Card transitionCard(String token,String id,String action,String reason){return core.post().uri("/core/cards/{id}/transition",id).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).body(Map.of("action",action,"reason",reason)).retrieve().body(Card.class);}
 public Posting post(String token,String requestId,String operation,String customerId,BigDecimal amount){return core.post().uri("/core/postings").header(HttpHeaders.AUTHORIZATION,"Bearer "+token).body(Map.of("requestId",requestId,"operation",operation,"customerId",customerId,"amount",amount)).retrieve().body(Posting.class);}
 public List<Staff> staff(String token){Staff[] x=entitlements.get().uri("/internal/staff").header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().body(Staff[].class);return x==null?List.of():List.of(x);}
 public Staff createStaff(String token,StaffCreate form){return entitlements.post().uri("/internal/staff").header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).body(form).retrieve().body(Staff.class);}
 public void resetPassword(String employeeId,String password){entitlements.post().uri("/internal/password-reset").header("X-Internal-Client",secret).body(Map.of("employeeId",employeeId,"password",password)).retrieve().toBodilessEntity();}
 public List<DelegationView> delegations(String token){DelegationView[]x=entitlements.get().uri("/internal/delegations").header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().body(DelegationView[].class);return x==null?List.of():List.of(x);}public void createDelegation(String token,DelegationCreate d){entitlements.post().uri("/internal/delegations").header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).body(d).retrieve().toBodilessEntity();}public void revokeDelegation(String token,long id){entitlements.post().uri("/internal/delegations/{id}/revoke",id).header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().toBodilessEntity();}public void setEnabled(String token,String id,boolean value){entitlements.patch().uri(u->u.path("/internal/staff/{id}/enabled").queryParam("value",value).build(id)).header("X-Internal-Client",secret).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).retrieve().toBodilessEntity();}
 @JsonIgnoreProperties(ignoreUnknown=true) public record Login(String token,String employeeId,String email,String role,String scope){}
 public record Decision(boolean allowed,String scope,String role,BigDecimal actAloneThreshold,BigDecimal approvalLimit,String authorizationBasis){}
 @JsonIgnoreProperties(ignoreUnknown=true) public record Customer(String id,String fullName,String phone,String email,String branch,boolean vulnerable){}
 @JsonIgnoreProperties(ignoreUnknown=true) public record Account(String accountNumber,String customerId,String product,String currency,String status,BigDecimal balance){}
 @JsonIgnoreProperties(ignoreUnknown=true) public record Card(String id,String accountNumber,String customerId,String maskedNumber,String status,String blockReason,String replacementOf){}
 public record Customer360(Customer customer,List<Account> accounts,List<Card> cards){}
 @JsonIgnoreProperties(ignoreUnknown=true) public record Posting(String requestId,String coreReference){}
 public record Staff(String employeeId,String email,String role,String homeBranch,String region,boolean enabled,BigDecimal actAloneThreshold,BigDecimal approvalLimit){}
 public record StaffCreate(String employeeId,String email,String role,String homeBranch,String region,String temporaryPassword){}
 public record DelegationView(long id,String delegatorId,String delegateId,String grantedScope,BigDecimal grantedLimit,LocalDate startDate,LocalDate endDate,String status){}public record DelegationCreate(String delegatorId,String delegateId,String grantedScope,BigDecimal grantedLimit,LocalDate startDate,LocalDate endDate){}
}
